int main(void) {
    size_t i;
    double d;
    float f;
    long double ld;
    int r;
    for (i = 0; i < sizeof nums / sizeof nums[0]; i++) {
        r = sscanf(nums[i], "%lf", &d);
        printf("%d %a", r, d);
        r = sscanf(nums[i], "%f", &f);
        printf(" %d %a\n", r, (double)f);
    }
    /* long double: its format is the target's; these are exact in each */
    r = sscanf("0.375 -2.5e3 0x1.8p-3", "%Lf %Le %La", &ld, &ld, &ld);
    printf("%d %La\n", r, ld);
    /* widths: the item stops at the width */
    {
        double d2 = 0;
        r = sscanf("3.14159", "%4lf%lf", &d, &d2);
        printf("%d %g %g\n", r, d, d2);
    }
    r = sscanf("1e5", "%2lf", &d);
    printf("%d\n", r);
    r = sscanf("-infinity nanx", "%lf %lf", &d, &d);
    printf("%d %f\n", r, d);
    return 0;
}
